                gs.info("----- Processing Single Payload Attributes -----");

                var payLoadValue = getPayload.PAYLOAD;

                id = payLoadValue.id ? payLoadValue.id : "";
                resourceType = payLoadValue.meta.resourceType;
                location = payLoadValue.meta.location;
                bubbleId = payLoadValue.bubbleId;
                organisationName = payLoadValue.organisationName;
                functionName = payLoadValue['function'];
                name = payLoadValue.contributor.name;
                email = payLoadValue.contributor.email;
                isSideLead = payLoadValue.isSideLead;
                organisationIsChair = payLoadValue.organisationIsChair;
                businessUnit = payLoadValue.businessUnit;
                businessUnitEmailAddress = payLoadValue.businessUnitEmailAddress;
                businessUnitRegion = payLoadValue.businessUnitRegion;
                type = payLoadValue.type;
                status = payLoadValue.status;

                gs.info('id ' + id);
                gs.info('resourceType ' + resourceType);
                gs.info('location ' + location);
                gs.info('bubbleId ' + bubbleId);
                gs.info('organisationName ' + organisationName);
                gs.info('functionName ' + functionName);
                gs.info('name ' + name);
                gs.info('email ' + email);
                gs.info('isSideLead ' + isSideLead);
                gs.info('organisationIsChair ' + organisationIsChair);
                gs.info('businessUnit ' + businessUnit);
                gs.info('businessUnitEmailAddress ' + businessUnitEmailAddress);
                gs.info('businessUnitRegion ' + businessUnitRegion);
                gs.info('type ' + type);
                gs.info('status ' + status);

                gs.info('------------------------------------------------------');
                //gs.info('cashValue ' + cashValue);

            } else {
                gs.info("No attributes found in payload");
            }


        } catch (ex) {
            gs.info('Error From MSS Taskize Bubble Create/Update: ' + ex);
        }
    },


