    createOutbound: function() {
        var recordId = this.getParameter('sysparm_record_id');
        var message = this.getParameter('sysparm_message');

        gs.info('Taskize Record ' + recordId);
        gs.info('Taskize Message ' + message);

        if (gs.nil(recordId) || gs.nil(message)) {
            return "error";
        }

        var gr = new GlideRecord('x_938076_now_utils_taskize_outbound');
        gr.initialize();
        gr.parent_record = recordId;
        gr.request_body = message;
        gr.request_date = new GlideDateTime();
        gr.response_body = ''; // Initialize response as empty
        gr.response_date = '';
        gr.active = true;

        var sysId = gr.insert();

        if (sysId) {
            return "success";
        } else {
            return "error";
        }


    },

    getMacroHTML: function() {
        // server-side GlideRecord fetch + Jelly rendering
        return sn_ws.getContent(new GlideRecord('x_938076_now_utils_taskize_outbound'));
    },
    type: 'base64Conversions'
});
